const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const {spawnSync}=require('node:child_process');
const manifest=require('../docs/source-manifest.json');
for(const [file,hash]of Object.entries(manifest.unchanged_files)){
  assert.equal(crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'),hash,file+' differs from migration source');
}
/* Pipeline outputs are regenerated by tools/overhead_*.py on a schedule
   (.github/workflows/overhead-data.yml), so they are validated by schema, provenance and content
   rather than by a frozen byte hash. Freezing them made every legitimate refresh fail the whole
   suite: the 2026-10-16 celestial refresh changed comet-ephemerides.json, which broke npm test on
   main with no push-triggered workflow running to show it. The scientific guarantee is unchanged and
   lives where it belongs: tools/overhead_comets_build.py --check and the meteors --check in CI, plus
   tests/overhead-comets-data.cjs and tests/overhead-meteors-data.cjs. The migration-time digest is
   kept in the manifest as history, not as an assertion. */
for(const [file,spec]of Object.entries(manifest.pipeline_outputs||{})){
  assert.equal(manifest.unchanged_files[file],undefined,file+' must not also be frozen as unchanged');
  assert.ok(fs.existsSync(file),'missing pipeline output '+file);
  const artifact=JSON.parse(fs.readFileSync(file,'utf8'));
  assert.equal(artifact.schema,spec.schema,file+' schema');
  assert.ok(Number.isFinite(Date.parse(artifact.generated_at)),file+' needs a generation time');
  assert.ok(Array.isArray(artifact[spec.list])||artifact[spec.list]&&typeof artifact[spec.list]==='object',file+' must contain '+spec.list);
  const list=artifact[spec.list];
  const size=Array.isArray(list)?list.length:Object.keys(list||{}).length;
  assert.ok(size>0,file+' must contain a non-empty '+spec.list);
  const provenance=artifact[spec.provenance];
  assert.ok(provenance&&typeof provenance==='object'&&Object.keys(provenance).length,file+' must record its '+spec.provenance);
  assert.ok(JSON.stringify(provenance).length>40,file+' provenance must name where the artifact came from');
  assert.ok(fs.existsSync(spec.builder),'missing builder '+spec.builder);
  assert.match(String(spec.migration_sha256),/^[0-9a-f]{64}$/,file+' keeps its migration digest for history');
}
const html=fs.readFileSync('index.html','utf8');
assert.match(html,/<title>Worth Looking Up/);
assert.match(html,/data-site-id="worthlookingup"/);
assert.match(html,/rel="canonical" href="https:\/\/worthlookingup.com\/"/);
assert.doesNotMatch(html,/https?:\/\/[^\s'"<>]*junkdrawer/i);
assert.doesNotMatch(html,/data-junkdrawer|data-site-id="junkdrawer"/);
const markup=html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/g,m=>m.slice(0,m.indexOf('>')+1));
for(const match of markup.matchAll(/(?:src|href)="([^"#?]+)"/g)){
  if(/^(https?:|data:)/.test(match[1]))continue;
  assert.ok(fs.existsSync(match[1]),'Missing HTML asset '+match[1]);
}
for(const worker of ['overhead-worker.js','overhead-celestial-worker.js']){
  const text=fs.readFileSync(worker,'utf8');
  for(const block of text.matchAll(/importScripts\(([^)]+)\)/g))for(const file of block[1].matchAll(/'([^']+)'/g))assert.ok(fs.existsSync(file[1]),worker+' missing '+file[1]);
}
// The calendar serializer is pure and local-first: no DOM, storage, network or framework, and it is
// the only module that writes iCalendar.
const calendar=fs.readFileSync('overhead-calendar.js','utf8');
assert.match(html,/src="overhead-calendar\.js"/,'index.html must load the calendar module');
assert.match(calendar,/BEGIN:VCALENDAR/);
assert.match(calendar,/PRODID/);
assert.match(calendar,/\\r\\n/);
for(const forbidden of [/\bdocument\./,/\blocalStorage\b/,/\bindexedDB\b/,/\bfetch\(/,/\bXMLHttpRequest\b/,/require\('https?/])
  assert.doesNotMatch(calendar,forbidden,'overhead-calendar.js must not use '+forbidden);
for(const file of ['overhead-discovery.js','overhead-launches.js'])
  assert.ok(fs.readFileSync(file,'utf8').includes('module.exports'),file+' stays loadable outside the browser');
assert.doesNotMatch(html,/<script[^>]+(?:googleapis|graph\.microsoft|calendar\.google)/i,'no calendar provider script may be introduced');
assert.doesNotMatch(calendar,/oauth|googleapis|graph\.microsoft/i,'the calendar module must stay free of provider APIs');
const versions=[...html.matchAll(/(?:version="|data-deploy-version="|· version )(\d{4}\.\d{2}\.\d{2}\.\d+)/g)].map(x=>x[1]);
assert.equal(versions.length,3);assert.equal(new Set(versions).size,1);
const transfer=require('../preferences-transfer.js');
const site={name:'Princeton',lat:38.3,lon:-87.5,tz:'America/Chicago'};
const input={schema:'worthlookingup.preferences/1',values:{site,sites:[site],favorites:['25544'],theme:'light',settings:{minimum:'20',score:50,show:'likely',units:'metric',clock:'24'}}};
class Storage{
  constructor(){this.map=new Map([['overhead.theme','dark'],['unrelated','preserve']]);this.fail=null;}
  getItem(k){return this.map.get(k)??null;}
  setItem(k,v){if(k===this.fail)throw Error('quota');this.map.set(k,v);}
  removeItem(k){this.map.delete(k);}
}
const storage=new Storage();transfer.apply(input,storage);assert.deepEqual(transfer.snapshot(storage),input);assert.equal(storage.getItem('unrelated'),'preserve');
for(const bad of [
  {...input,schema:'other'},
  {...input,values:{site:{...site,lat:100}}},
  {...input,values:{site:{...site,tz:'invented/zone'}}},
  {...input,values:{sites:Array(13).fill(site)}},
  {...input,values:{favorites:Array(101).fill('25544')}},
  {...input,values:{'analytics.visitor_id':'must not import'}},
  {...input,values:{settings:{...input.values.settings,score:101}}}
])assert.throws(()=>transfer.apply(bad,new Storage()));
const failed=new Storage();failed.fail='overhead.favorites';assert.throws(()=>transfer.apply(input,failed));assert.equal(failed.getItem('overhead.site'),null);assert.equal(failed.getItem('overhead.theme'),'dark');
assert.equal(spawnSync(process.execPath,['scripts/build.cjs'],{stdio:'inherit'}).status,0);
for(const forbidden of ['.git','.env','tests','tools','node_modules','package.json','agents.md'])assert.ok(!fs.existsSync(path.join('dist',forbidden)),forbidden+' leaked into deployment');
assert.ok(fs.existsSync('dist/404.html'));
assert.match(fs.readFileSync('dist/_redirects','utf8'),/^\/overhead\.html https:\/\/worthlookingup.com\/ 301$/m);
assert.equal(fs.readFileSync('dist/_worker.js','utf8'),fs.readFileSync('pages-worker.mjs','utf8'));
// The staged Worker must resolve every relative import inside the deployment directory.
for(const match of fs.readFileSync('dist/_worker.js','utf8').matchAll(/from\s+'(\.[^']+)'/g)){
  const target=path.resolve('dist',match[1]);
  assert.ok(target.startsWith(path.resolve('dist')+path.sep),'Worker import escapes the deployment: '+match[1]);
  assert.ok(fs.existsSync(target),'Worker import is not staged: '+match[1]);
}
assert.ok(fs.existsSync('dist/data/launches/upcoming.json'),'the launch feed is not staged');
assert.ok(fs.existsSync('dist/overhead-launches.js'),'the launch calendar module is not staged');
function walk(dir){for(const e of fs.readdirSync(dir,{withFileTypes:true})){
  if(['.git','node_modules','.wrangler','test-results','playwright-report'].includes(e.name))continue;
  assert.equal(e.name,e.name.toLowerCase(),'Non-lowercase path '+e.name);
  const file=path.join(dir,e.name);if(e.isDirectory())walk(file);
}}
walk('.');
console.log('PASS: unchanged scientific source, local assets and worker imports, canonical/analytics identity, lowercase paths, release versions, bounded preference validation/rollback, deployment allowlist.');
